        if (g === 'confier') { dosState.confier = d.id; redessiner(); }
        if (g === 'noter') fenNoterRelance(d, [...tard, ...(etatMoisFd(d, mp, L, tard, mc)[0] === 'manque' ? [mp] : [])]);
        if (g === 'appeler') { try { await api.tel({ number: d.phone }); } catch (x2) { toast(plainError(x2), 'error'); } }
