  const motsCl = t => sansAccentsCl(t).split(/[^a-z0-9]+/).filter(w => w.length > 2 && !/^\d+$/.test(w) && !MOTS_VIDES_CL.has(w));
  // Ce que vendent les fournisseurs que tout le monde connaît : « facture-electricite » est celle de la STEG, même si
